script:
// ============ KÖRÖKRE OSZTOTT REAKCIÓS HARC v2 + BILLENTYŰZET + OPTIMALIZÁLVA + FPS-SZÁMLÁLÓ / TURN-BASED REACTIVE COMBAT v2 + KEYBOARD + OPTIMISED + FPS COUNTER ============
// Billentyűk: F = parírozás · A = támadás · S = erős csapás · D = forgószél · H = gyógyítás · G = védekezés / Keys: F = parry · A = attack · S = power strike · D = whirlwind · H = heal · G = guard
// C = időzítő gyűrű · V = effektek · B = mozifilm-sávok · Q = FPS-számláló · U = minőség · Enter = újrakezdés / C = timing ring · V = effects · B = letterbox bars · Q = FPS counter · U = quality · Enter = restart
stage(1000, 600, "#07050d");
title({hu: "Körökre osztott harc – paríroz!", en: "Turn-based combat – parry!"}, {color: "#e8dcc8"});
plotWindow(30);

// --- vezérlők (minden gombnak van billentyűje is; a billentyű a feliratban látszik) / controls (every button also has a key; the key is shown in its label) ---
button({hu: "PARÍROZÁS [F]", en: "PARRY [F]"}, () => doParry(), {key: "f"});
button({hu: "Támadás [A] (ingyen, +1 energia)", en: "Attack [A] (free, +1 energy)"}, () => doAct("attack"), {key: "a"});
button({hu: "Erős csapás [S] (3 energia)", en: "Power strike [S] (3 energy)"}, () => doAct("power"), {key: "s"});
button({hu: "Forgószél [D] (4 energia)", en: "Whirlwind [D] (4 energy)"}, () => doAct("whirl"), {key: "d"});
button({hu: "Gyógyítás [H] (3 energia)", en: "Heal [H] (3 energy)"}, () => doAct("heal"), {key: "h"});
button({hu: "Védekezés [G] (+1 energia)", en: "Guard [G] (+1 energy)"}, () => doAct("guard"), {key: "g"});
button({hu: "Újrakezdés [Enter]", en: "Restart [Enter]"}, reset, {key: "Enter"});

param("win", {hu: "Parírozási ablak (±)", en: "Parry window (±)"}, 0.08, 0.4, 0.17, 0.01, "s");   // a korai oldal ez az érték, a késői oldal ennek 60 %-a / early side = this value, late side = 60 % of it
param("dmg", {hu: "Ellenség alapsebzése", en: "Enemy base damage"}, 4, 30, 9, 1, "HP");           // minden támadástípus ezt szorozza / each attack type multiplies this
param("spd", {hu: "Ellenség tempója", en: "Enemy tempo"}, 0.6, 1.5, 1, 0.05, "×");
param("shk", {hu: "Kamerarázkódás", en: "Camera shake"}, 0, 2, 1, 0.1, "×");
toggle("cue", {hu: "Időzítő gyűrű (segítség) [C]", en: "Timing ring (helper) [C]"}, true, {key: "c"});
toggle("fx", {hu: "Parázs, köd, fénysugarak [V]", en: "Embers, fog, light shafts [V]"}, true, {key: "v"});
toggle("bars", {hu: "Mozifilm-sávok [B]", en: "Letterbox bars [B]"}, true, {key: "b"});
toggle("fpsOn", {hu: "FPS-számláló [Q]", en: "FPS counter [Q]"}, true, {key: "q"});
// Grafikai minőség: az „auto” magason indul, és magától lejjebb lép, ha az FPS tartósan alacsony / Graphics quality: "auto" starts on high and steps down by itself if the frame rate stays low
choice("qual", {hu: "Grafikai minőség [U]", en: "Graphics quality [U]"},
  [["auto", {hu: "Automatikus (az FPS alapján)", en: "Auto (adapts to FPS)"}],
   ["high", {hu: "Magas", en: "High"}], ["med", {hu: "Közepes", en: "Medium"}], ["low", {hu: "Alacsony", en: "Low"}]], "auto", {key: "u"});

// ---------- állandók / constants ----------
const MAXHP = 130, MAXEH = 500, MAXEN = 8;      // a játékos HP-ja, az ellenség HP-ja, a maximális energia / player HP, enemy HP, max energy
const BASEZ = -5.6;                              // az ellenség állóhelye (z, m) / enemy standing position (z, m)
const PX = -1.0, PZ = 1.0;                       // a játékos kiinduló helye (x, z) / player home position (x, z)
const SX = -0.6, SZ = BASEZ + 2.3;               // ahol a játékos áll, amikor megüti az ellenséget / where the player stands to hit the enemy
const NEARP = 0.2;                               // közeli vágósík (m) / near clipping plane (m)
const AX = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];    // a világ tengelyei / world axes
const LIGHT = norm3([-0.4, 0.8, 0.5]);           // irány a fő fényforrás felé / direction towards the main light
const FOGC = [34, 24, 54];                       // a köd színe / fog colour
const MOON = norm3([0.35, 0.42, -0.84]);         // irány a hold felé / direction towards the moon
const ARC = [0, -3];                             // az aréna közepe (x, z) / arena centre (x, z)
const COST = {attack: 0, power: 3, whirl: 4, heal: 3, guard: 0};   // energiaköltségek / energy costs
// a játékos akciói: end = teljes hossz (s), hits = a találatok pillanatai (s), dmg = az egyes találatok sebzése, / player actions: end = total length (s), hits = moments a hit lands (s), dmg = damage of each hit,
// ret = amikor a kamera visszatér a totálra, eff = egy nem sebző hatás pillanata / ret = time when the camera returns to the wide shot, eff = moment of a non-damage effect
const ACT = {
  attack: {end: 1.35, hits: [0.5], dmg: [20], ret: 0.8},
  power:  {end: 1.8, hits: [0.9], dmg: [52], ret: 1.2},
  whirl:  {end: 1.85, hits: [0.6, 0.85, 1.1], dmg: [22, 22, 22], ret: 1.3},
  heal:   {end: 1.45, hits: [], dmg: [], ret: 0.9, eff: 0.85},
  guard:  {end: 1.2, hits: [], dmg: [], ret: 0.9, eff: 0.3}
};
const GLC = {heal: [125, 255, 176], power: [255, 176, 96], whirl: [111, 224, 255], block: [191, 240, 255], win: [255, 224, 138], guard: [138, 200, 255]};

// Minőségi szintek: 0. index = alacsony, 1 = közepes, 2 = magas. Minden elem megmondja, mennyi opcionális részlet rajzolódik: / Quality levels: index 0 = low, 1 = medium, 2 = high. Each entry says how much optional detail is drawn:
// sky = egy égsáv magassága (px, nagyobb = kevesebb téglalap), stars = csillagok száma, seg = melyik padlófelosztás (0: 12, 1: 16, 2: 24 cikk), / sky = height of one sky band (px, bigger = fewer rectangles), stars = number of stars, seg = which floor tessellation (0: 12, 1: 16, 2: 24 sectors),
// vig = vignetta stílusa, grain = filmszemcse-pöttyök, emb = parázs, trail = kardnyom-minták, ring = a rúnagyűrűk szakaszai, / vig = vignette style, grain = film-grain dots, emb = embers, trail = sword-trail samples, ring = segments of the rune rings,
// shaft = holdfény-sugarak, fog = ködrétegek a horizonton / shaft = moon light shafts, fog = horizon fog layers
const QS = [
  {sky: 24, stars: 20, seg: 0, grain: 0,  emb: 8,  trail: 5,  ring: 20, shaft: 0, fog: 0},
  {sky: 16, stars: 40, seg: 1, grain: 8,  emb: 20, trail: 8,  ring: 28, shaft: 3, fog: 3},
  {sky: 12, stars: 70, seg: 2, grain: 30, emb: 36, trail: 12, ring: 40, shaft: 5, fog: 6}
];
const QN = [{hu: "alacsony", en: "low"}, {hu: "közepes", en: "medium"}, {hu: "magas", en: "high"}];

// Az ellenség kardpózai: [kéz x, kéz y, kéz z, szög, dőlés] az ellenség talpához képest (m). / Enemy sword poses: [hand x, hand y, hand z, angle, tilt] relative to the enemy's feet (m).
// A kard iránya = (sin(ang)·cos(tilt), cos(ang)·cos(tilt), sin(tilt)); ang 0 = fel, 180° = le; tilt + = feléd. / Sword direction = (sin(ang)·cos(tilt), cos(ang)·cos(tilt), sin(tilt)); ang 0 = up, 180° = down; tilt + = towards you.
const PR = [0.6, 1.2, 0.3, deg(160), deg(20)];            // nyugalmi helyzet / rest
const DEAD = [0.5, 0.4, 0.4, deg(172), deg(8)];           // lelógó kard a vereség után / sword drooping after defeat
// Az ellenség 8 támadása. wu = felhúzó póz, hit = becsapódási póz, wind = alap felhúzási idő (s), / The 8 enemy attacks. wu = wind-up pose, hit = impact pose, wind = base wind-up time (s),
// heN / heD = a felhúzás mekkora része után indul a gyors csapás (normál / késleltetett), / heN / heD = fraction of the wind-up after which the fast strike starts (normal / delayed),
// L = előrelépés hossza (m), spin = teljes fordulatok a csapás alatt, jump = lebegési magasság (m), dm = sebzésszorzó, cl = jelzőszín / L = lunge distance (m), spin = full turns during the strike, jump = hover height (m), dm = damage multiplier, cl = telegraph colour
const AT = [
  {nm: "↙", name: {hu: "Átlós vágás", en: "Diagonal slash"}, cl: [255, 179, 71], wu: [1.0, 2.2, 0.15, deg(50), deg(-10)], hit: [-0.5, 1.4, 1.1, deg(-85), deg(25)], wind: 0.62, heN: 0.68, heD: 0.85, L: 3.4, spin: 0, jump: 0, dm: 1},
  {nm: "↘", name: {hu: "Fordított vágás", en: "Reverse slash"}, cl: [255, 179, 71], wu: [-0.1, 2.3, 0.1, deg(-40), deg(-10)], hit: [1.2, 1.4, 1.1, deg(85), deg(25)], wind: 0.62, heN: 0.68, heD: 0.85, L: 3.4, spin: 0, jump: 0, dm: 1},
  {nm: "↓", name: {hu: "Lesújtás", en: "Overhead slam"}, cl: [255, 122, 74], wu: [0.5, 2.9, -0.1, deg(10), deg(-50)], hit: [0.3, 1.5, 1.5, deg(160), deg(50)], wind: 0.8, heN: 0.7, heD: 0.86, L: 3.9, spin: 0, jump: 0, dm: 1.4},
  {nm: "●", name: {hu: "Szúrás", en: "Thrust"}, cl: [95, 208, 255], wu: [0.8, 1.5, -0.5, deg(60), deg(75)], hit: [0.1, 1.6, 1.7, deg(90), deg(85)], wind: 0.7, heN: 0.68, heD: 0.85, L: 4.2, spin: 0, jump: 0, dm: 1.1},
  {nm: "↻", name: {hu: "Forgó vágás", en: "Spin slash"}, cl: [199, 125, 255], wu: [1.1, 1.6, 0.0, deg(95), deg(0)], hit: [-0.5, 1.4, 1.1, deg(-85), deg(25)], wind: 1.05, heN: 0.55, heD: 0.78, L: 3.6, spin: 1, jump: 0, dm: 1.3},
  {nm: "↑", name: {hu: "Felfelé vágás", en: "Rising cut"}, cl: [125, 255, 176], wu: [0.7, 0.7, 0.5, deg(150), deg(25)], hit: [0.2, 2.2, 1.4, deg(-20), deg(40)], wind: 0.75, heN: 0.68, heD: 0.85, L: 3.5, spin: 0, jump: 0, dm: 1.1},
  {nm: "▼", name: {hu: "Ugró zúzás", en: "Leap smash"}, cl: [255, 80, 80], wu: [0.5, 3.1, -0.1, deg(10), deg(-55)], hit: [0.3, 1.0, 1.7, deg(170), deg(55)], wind: 1.2, heN: 0.74, heD: 0.88, L: 4.2, spin: 0, jump: 2.1, dm: 1.6},
  {nm: "↻↻", name: {hu: "Vihar (dupla pörgés)", en: "Tempest (double spin)"}, cl: [255, 74, 138], wu: [1.2, 1.7, 0.0, deg(95), deg(0)], hit: [1.2, 1.4, 1.2, deg(80), deg(15)], wind: 1.5, heN: 0.5, heD: 0.75, L: 3.8, spin: 2, jump: 0, dm: 1.8}
];
// A játékos kardpózai (a játékos −z felé néz; kéz x = jobbra, tilt + = az ellenség felé). Az ang/tilt jelentése ugyanaz, mint fent. / Player sword poses (player faces −z; hand x = right, tilt + = towards the enemy). Same meaning of ang/tilt as above.
const IDL = [0.38, 1.0, -0.3, deg(15), deg(40)];          // készenléti állás / ready stance
const GP = [0.05, 1.15, -0.55, deg(85), deg(55)];         // védekező állás / guard stance
const PBL = [[0.35, 1.5, -0.35, deg(35), deg(30)], [-0.1, 1.5, -0.35, deg(-35), deg(30)], [0.1, 1.75, -0.25, deg(90), deg(20)],
             [0.15, 1.1, -0.5, deg(10), deg(80)], [0.35, 1.3, -0.3, deg(80), deg(10)], [0.4, 0.8, -0.35, deg(120), deg(30)],
             [0.1, 1.8, -0.25, deg(90), deg(25)], [0.35, 1.3, -0.3, deg(80), deg(10)]];   // hárító póz minden támadástípus ellen / block pose against each attack type

// ---------- a játék állapota / game state ----------
let phase = "player";                            // játékos, játékos akciója, ellenség, győzelem, vereség / player, pAct, enemy, won, lost
let hp = MAXHP, ehp = MAXEH, nrg = 3, turn = 1;
let guard = false, stagger = false;              // a védekezés felezi a sebzést; stagger = az ellenség +50 %-ot kap a következő akciódtól / guard halves damage; stagger = enemy takes +50 % on your next action
let pt = 0, hitIdx = 0, effDone = false, actKind = "attack";   // a játékos akciójának időzítője / player action timer
let combo = [], et = -1;                         // az ellenség kombója és annak órája (s) / enemy combo and its clock (s)
let freeze = 0, lock = 0, recoilT = 0;           // találati megállás, parírozási zár egy elhibázott után, az ellenség hátrahőkölése / hit-stop, parry lock after a whiff, enemy recoil
let tm = 0, sparkT = 9, shakeT = 0, hurtT = 0, eflash = 0, zoomK = 0, blockT = 0, blockTy = 0, impT = 0;   // effekt-időzítők / effect timers
let zOff = 0;                                    // az ellenség előrelépése (m) / enemy lunge distance (m)
let cEye = [2.6, 1.7, 3.6], cAim = [-0.7, 1.6, -2.6], cFL = 620;   // simított kamera / smoothed camera
let hpShow = MAXHP, ehpShow = MAXEH;             // simán animált sávok / smoothly animated bars
let sparkW = [0, 1.5, BASEZ];                    // az utolsó parírozási szikrák helye a világban / world position of the last parry sparks
let msgL = "", msgC = "#fff", msgT = 0;          // nagy üzenet középen / big centre message
let pops = [];                                   // lebegő sebzésszámok / floating damage numbers
let parries = 0, parryNrg = 0;
setMsg({hu: "A te köröd", en: "Your turn"}, "#e8dcc8");

// ---------- FPS-számláló és automatikus minőség (csak a megjelenítéshez, a játék állapotához sosem nyúl) / FPS counter and automatic quality (presentation only, it never touches the game state) ----------
// A VALÓDI időt méri a kirajzolt képkockák között, így nem függ a Sebesség csúszkától és a szünettől. / It measures REAL time between drawn frames, so it does not depend on the Speed slider or on pause.
// A Date.now()-t használja (szabványos JavaScript). Ha a homokozó letiltja az órát, a számláló „n/a”-t mutat. / It uses Date.now() (standard JavaScript). If the sandbox blocks the clock, the counter shows "n/a".
let fpsStart = 0, fpsLast = 0, fpsAcc = 0, fpsN = 0, fpsVal = 0, frameMs = 0, fpsOk = true;
let slowN = 0, ql = 2, lastQual = "auto";        // ql = az „auto” módban használt minőségi szint (magason indul) / ql = quality level used in "auto" mode (starts on high)
const nowMs = () => { try { return Date.now(); } catch (err) { return 0; } };
function fpsTick() {                             // minden draw elején egyszer hívódik / called once at the start of every draw
  const n = nowMs();
  if (n <= 0) { fpsOk = false; return; }
  if (fpsStart === 0) fpsStart = n;
  if (P.qual !== lastQual) { lastQual = P.qual; slowN = 0; if (P.qual === "auto") ql = 2; }   // az „auto” újbóli kiválasztása magasról indít újra / choosing "auto" again restarts from high
  if (fpsLast > 0) {
    const d = n - fpsLast;
    if (d > 0 && d < 1000) { fpsAcc += d; fpsN++; }          // az 1 s-nál hosszabb akadásokat (rejtett lap) figyelmen kívül hagyja / stalls longer than 1 s (hidden tab) are ignored
    if (fpsAcc >= 500) {                                     // 0,5 s-onként: új átlag / every 0.5 s: a new average
      fpsVal = 1000 * fpsN / fpsAcc; frameMs = fpsAcc / fpsN; fpsAcc = 0; fpsN = 0;
      if (P.qual === "auto" && n - fpsStart > 2500) {        // az első 2,5 s alatt nincs döntés (bemelegítés) / no decisions during the first 2.5 s (warm-up)
        slowN = fpsVal < 45 ? slowN + 1 : 0;                 // 3 lassú ablak egymás után (1,5 s) → egy szinttel lejjebb / 3 slow windows in a row (1.5 s) → one level lower
        if (slowN >= 3 && ql > 0) { ql--; slowN = 0; }
      }
    }
  }
  fpsLast = n;
}

// ---------- segédfüggvények / helpers ----------
function sstep(a, b, x) { const k = clamp((x - a) / (b - a), 0, 1); return k * k * (3 - 2 * k); }
function ss(a, b, x) { return sstep(a, b, x); }
function hash(i, j) { const s = sin(i * 12.9898 + j * 78.233) * 43758.5453; return s - floor(s); }
function dot3(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
function add3(a, b) { return [a[0] + b[0], a[1] + b[1], a[2] + b[2]]; }
function sub3(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function mul3(a, k) { return [a[0] * k, a[1] * k, a[2] * k]; }
function cross3(a, b) { return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]; }
function norm3(a) { return mul3(a, 1 / max(sqrt(dot3(a, a)), 1e-9)); }
function lerpA(a, b, k) { return a.map((v, i) => v + (b[i] - v) * k); }
function mix(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }
function rgb(c) { return "rgb(" + floor(clamp(c[0], 0, 255)) + "," + floor(clamp(c[1], 0, 255)) + "," + floor(clamp(c[2], 0, 255)) + ")"; }
function setMsg(label, col) { msgL = label; msgC = col; msgT = 1; }

// forgatás a függőleges tengely körül (a > 0 a helyi +x-et −z felé fordítja); a „rig” = {o: origó, ya: elfordulás} / rotation about the vertical axis (a > 0 turns local +x towards −z); a "rig" = {o: origin, ya: yaw}
// (a cos/sin és az elforgatott tengelyek a rigben tárolódnak, így egy kb. 25 részből álló alak képkockánként csak egyszer forog) / (cos/sin and the rotated axes are cached inside the rig, so a figure with ~25 parts rotates only once per frame)
function rotY(v, a) { const c = cos(a), s = sin(a); return [v[0] * c + v[2] * s, v[1], -v[0] * s + v[2] * c]; }
function rp(rg, v) {
  if (rg.cs === undefined) { rg.cs = cos(rg.ya); rg.sn = sin(rg.ya); }
  return [rg.o[0] + v[0] * rg.cs + v[2] * rg.sn, rg.o[1] + v[1], rg.o[2] - v[0] * rg.sn + v[2] * rg.cs];
}
function raxes(rg) { if (!rg.ax) rg.ax = [rotY([1, 0, 0], rg.ya), [0, 1, 0], rotY([0, 0, 1], rg.ya)]; return rg.ax; }
function rbox(items, rg, c, hs, col, bias, em, fa, fc) { obox(items, rp(rg, c), raxes(rg), hs, col, bias, em, fa, fc); }
function rbar(items, rg, a, b, h1, h2, col, bias, em, fa, fc) { bar2(items, rp(rg, a), rp(rg, b), h1, h2, col, bias, em, fa, fc); }

// ---------- az ellenség póza, pörgése, ugrása / enemy pose, spin, jump ----------
function swordDir(po) { return [sin(po[3]) * cos(po[4]), cos(po[3]) * cos(po[4]), sin(po[4])]; }
function tipOf(rg, po, len) { return rp(rg, add3([po[0], po[1], po[2]], mul3(swordDir(po), len))); }
function curIdx(e) { let i = -1; for (let k = 0; k < combo.length; k++) if (combo[k].st <= e) i = k; return i; }
// Póz az e kombóidőben: nyugalom → felhúzás (szünettel a „késleltetett” csapásoknál) → gyors, gyorsuló csapás → kitartás → nyugalom. / Pose at combo time e: rest → wind-up (with a pause for "delayed" strikes) → fast accelerating strike → hold → rest.
function poseAt(e) {
  if (combo.length === 0 || e < 0) return PR;
  const i = curIdx(e);
  if (i < 0) return PR;
  const c = combo[i], A = AT[c.ty], from = i > 0 ? AT[combo[i - 1].ty].hit : PR;
  if (e < c.ht) {
    const u = (e - c.st) / c.wind;
    const a = sstep(0, c.he * 0.6, u);                         // a kard felemelése / raise the sword
    const b = pow(clamp((u - c.he) / (1 - c.he), 0, 1), 2);    // kitartás, majd csapás (gyorsulva) / hold, then strike (accelerating)
    return lerpA(lerpA(from, A.wu, a), A.hit, b);
  }
  if (i === combo.length - 1) return lerpA(A.hit, PR, sstep(c.ht + 0.25, c.ht + 0.95, e));
  return A.hit;
}
function yawAt(e) {                                            // a test 360°-ot / 720°-ot fordul a pörgő támadásoknál, a találatnál ér véget / body turns 360° / 720° during spin attacks, ending at the hit
  if (combo.length === 0 || e < 0) return 0;
  const i = curIdx(e);
  if (i < 0) return 0;
  const c = combo[i], A = AT[c.ty];
  if (A.spin === 0 || e >= c.ht) return 0;
  const b = clamp(((e - c.st) / c.wind - c.he) / (1 - c.he), 0, 1);
  return 2 * PI * A.spin * (0.35 * b + 0.65 * b * b);
}
function jumpAt(e) {                                           // az ugró lecsapás: felemelkedik, lebeg, lecsapódik / the leap smash: rise, hover, crash down
  if (combo.length === 0 || e < 0) return 0;
  const i = curIdx(e);
  if (i < 0) return 0;
  const c = combo[i], A = AT[c.ty];
  if (A.jump === 0 || e >= c.ht) return 0;
  const u = (e - c.st) / c.wind;
