// ---------- 2) FIZIKA / JÁTÉKLOGIKA / PHYSICS / GAME LOGIC ----------
update(dt => {
  if (freeze > 0) { freeze -= dt; return; }                    // találati megállás: egy pillanatra minden megáll / hit-stop: everything holds for a moment
  tm += dt;
  sparkT += dt; shakeT = max(0, shakeT - dt); hurtT = max(0, hurtT - dt); eflash = max(0, eflash - 3 * dt);
  zoomK = max(0, zoomK - 3 * dt); msgT = max(0, msgT - 0.7 * dt); lock = max(0, lock - dt);
  recoilT = max(0, recoilT - dt); blockT = max(0, blockT - dt); impT = max(0, impT - dt);
  let dead = false;                                            // egyetlen menet a lebegő számokon (nincs külön tömbbejárás minden lépésben) / one pass over the floating numbers (no extra array scan every step)
  for (const q of pops) { q.t -= 0.9 * dt; if (q.t <= 0) dead = true; }
  if (dead) pops = pops.filter(q => q.t > 0);
  hpShow += (hp - hpShow) * (1 - exp(-5 * dt));
  ehpShow += (ehp - ehpShow) * (1 - exp(-5 * dt));

  if (phase === "pAct") {
    pt += dt;
    const A = ACT[actKind];
    while (hitIdx < A.hits.length && pt >= A.hits[hitIdx]) { doHit(hitIdx); hitIdx++; }
    if (A.eff !== undefined && !effDone && pt >= A.eff) { effDone = true; doEffect(); }
    if (pt > A.end) { if (ehp <= 0) phase = "won"; else startEnemy(); }
  } else if (phase === "enemy") {
    et += dt;
    for (const c of combo) {                                   // a nem hárított csapások most találnak / strikes that were not parried land now
      if (phase !== "enemy") break;
      if (c.res === 0 && et > c.ht + P.win * 0.6) { c.res = 2; takeHit(c); }
    }
    if (phase === "enemy" && et > combo[combo.length - 1].ht + 0.95) endEnemyTurn();
  }

  // az ellenség előrelépése: minden csapás utolsó részében feléd lép; hátrahőköl parírozásra / találatra / enemy lunge: it steps towards you for the final part of every strike; recoil on parry / hit
  let tgt = 0;
  if (phase === "enemy" && et >= 0) {
    const i = curIdx(et);
    if (i >= 0) { const c = combo[i], u = (et - c.st) / c.wind; tgt = (u > 0.55 || et >= c.ht) ? c.L : 0.3 * c.L; }
  }
  if (recoilT > 0) tgt = -0.7;
