    const A = ACT[actKind];
    if (actKind === "heal" || actKind === "guard") { te = [2.4, 1.5, 3.0]; ta = [PX - 0.2, 1.2, PZ - 0.2]; tf = 720; rate = 4; }
    else if (pt < A.ret) {
