      te = [5.4, 1.6 + 0.15 * o.y, mz + 0.4]; ta = [-0.6, 1.5 + 0.35 * o.y, mz]; tf = actKind === "power" ? 600 : 560; rate = 6;
    } else rate = 3.5;
