    const dd = -(A[0] * qx + A[1] * qy + A[2] * qz);                      // A · (kamera − középpont): a doboz melyik oldalán van a kamera / A · (camera − centre): which side of the box the camera is on
    const al = A[0] * LIGHT[0] + A[1] * LIGHT[1] + A[2] * LIGHT[2];       // mennyire néz ez a tengely a fény felé / how much this axis faces the light
    const bx = B[0] * hb, by = B[1] * hb, bz = B[2] * hb, dx = D[0] * hd, dy = D[1] * hd, dw = D[2] * hd;
    for (let sg = -1; sg <= 1; sg += 2) {
      if (sg * dd <= hk) continue;                                        // hátsó lap / backface
      const ex = qx + sg * hk * A[0], ey = qy + sg * hk * A[1], ez = qz + sg * hk * A[2];   // a lap középpontja a kamerához képest / face centre relative to the camera
      const v = clipPoly([cv(ex + bx + dx, ey + by + dy, ez + bz + dw), cv(ex - bx + dx, ey - by + dy, ez - bz + dw),
                          cv(ex - bx - dx, ey - by - dy, ez - bz - dw), cv(ex + bx - dx, ey + by - dy, ez + bz - dw)]);
      if (v.length < 3) continue;
      const f = em ? 1.2 : 0.3 + 0.85 * max(0, sg * al) + 0.1 * max(0, sg * A[1]);   // egyszerű megvilágítás / simple lighting
      const lit = [cc[0] * f * 0.95, cc[1] * f * 0.98, cc[2] * f * 1.1];             // enyhén kékes holdfény / slightly blue moonlight
      polys.push({pts: v.map(scrP), col: rgb(em ? lit : mix(lit, FOGC, fogK))});
    }
  }
  if (polys.length) items.push({key: dz - (bias || 0), polys});
}
function bar2(items, a, b, h1, h2, col, bias, em, fa, fc) {    // téglalap alakú rúd az a ponttól a b pontig / a rectangular bar from point a to point b
  const d = sub3(b, a), L = sqrt(dot3(d, d)), w = mul3(d, 1 / max(L, 1e-6));
  let u = cross3(w, [0, 1, 0]);
  if (dot3(u, u) < 1e-4) u = [1, 0, 0];
  u = norm3(u);
  obox(items, mul3(add3(a, b), 0.5), [u, cross3(w, u), w], [h1, h2, L / 2], col, bias, em, fa, fc);
}
function flush(items) {                                        // festő-algoritmus: távolról közelre / painter's algorithm: far to near
  items.sort((p, q) => q.key - p.key);
  for (const it of items) for (const pl of it.polys) polygon(pl.pts, {fill: pl.col, stroke: pl.col, lw: 1});
}

// ---------- a Rozsdaőr (ellenség), dobozokból felépítve a saját helyi rendszerében (+z felé néz) / the Rust Warden (enemy), built from boxes in its own local frame (it faces +z) ----------
function addEnemy(items, rg, po, gl) {                         // gl = {c: jelzőszín, a: 0…1 a penge izzása} / gl = {c: telegraph colour, a: 0…1 blade glow}
  const fa = eflash, fc = [255, 255, 255];
  const part = (c, hs, col, em) => rbox(items, rg, c, hs, col, 0, em, fa, fc);
  const rune = gl.a > 0 ? mix([150, 70, 40], gl.c, gl.a) : [150, 70, 40];
  part([-0.2, 0.55, 0], [0.15, 0.55, 0.17], [44, 38, 54]);             // lábak / legs
  part([0.2, 0.55, 0], [0.15, 0.55, 0.17], [44, 38, 54]);
  part([0, 1.1, 0], [0.36, 0.13, 0.24], [60, 48, 40]);                 // csípő / hips
  part([0, 1.7, 0], [0.46, 0.6, 0.28], [92, 66, 52]);                  // törzs / torso
  part([0, 1.78, 0.28], [0.33, 0.38, 0.03], [130, 92, 60]);            // mellvért / chest plate
  part([0, 1.78, 0.315], [0.05, 0.28, 0.01], rune, true);              // izzó rúnák (felveszik a támadás színét) / glowing runes (they take the attack's colour)
  part([0, 1.98, 0.315], [0.2, 0.04, 0.01], rune, true);
  part([-0.66, 2.2, 0], [0.24, 0.14, 0.28], [110, 80, 58]);            // tüskés vállvértek / pauldrons with spikes
  part([0.66, 2.2, 0], [0.24, 0.14, 0.28], [110, 80, 58]);
  part([-0.72, 2.46, 0], [0.05, 0.16, 0.05], [160, 130, 96]);
  part([0.72, 2.46, 0], [0.05, 0.16, 0.05], [160, 130, 96]);
  part([0, 2.62, 0.02], [0.2, 0.24, 0.2], [74, 62, 76]);               // fej / head
  part([-0.24, 2.98, 0], [0.04, 0.2, 0.04], [190, 170, 140]);          // szarvak / horns
  part([0.24, 2.98, 0], [0.04, 0.2, 0.04], [190, 170, 140]);
  part([0, 2.64, 0.215], [0.15, 0.04, 0.012], phase === "won" ? [40, 30, 30] : stagger ? [140, 210, 255] : [255, 110, 60], true);   // sisakrostély / visor
  part([0.1 * sin(2 * tm), 1.75, -0.32], [0.45, 0.85, 0.03], [110, 34, 44]);   // lengő köpeny / cape, swaying
  const hand = [po[0], po[1], po[2]], dir = swordDir(po);
  rbar(items, rg, [0.62, 2.1, 0], hand, 0.11, 0.11, [96, 70, 54], 0, false, fa, fc);        // kardot tartó kar / sword arm
  rbar(items, rg, [-0.62, 2.1, 0], [-0.55, 1.3, 0.3], 0.1, 0.1, [96, 70, 54], 0, false, fa, fc);   // másik kar / other arm
  rbar(items, rg, sub3(hand, mul3(dir, 0.25)), add3(hand, mul3(dir, 0.45)), 0.05, 0.05, [40, 30, 28], 0.2, false, fa, fc);   // markolat / handle
  const steel = [176, 184, 200], bc = gl.a > 0 ? mix(steel, gl.c, gl.a) : steel;
  rbar(items, rg, add3(hand, mul3(dir, 0.45)), add3(hand, mul3(dir, 2.7)), 0.12, 0.03, bc, 0.2, gl.a > 0.55, fa, fc);   // a penge izzik, ha csapás jön / blade glows when a strike is coming
  const raw = cross3(dir, [0, 1, 0]), gu = norm3(dot3(raw, raw) < 1e-4 ? [1, 0, 0] : raw), gc = add3(hand, mul3(dir, 0.45));
  rbar(items, rg, sub3(gc, mul3(gu, 0.3)), add3(gc, mul3(gu, 0.3)), 0.04, 0.04, [150, 120, 60], 0.3, false, fa, fc);   // keresztvas / cross-guard
}

// ---------- a játékos alakja (−z felé néz) / the player character (it faces −z) ----------
function pDir(po) { return [sin(po[3]) * cos(po[4]), cos(po[3]) * cos(po[4]), -sin(po[4])]; }
function addPlayer(items, o, fa, fc) {
  const rg = {o: [o.x, o.y, o.z], ya: o.yaw};
  const hy = 0.9 - o.cr;                                       // csípőmagasság (guggolásnál alacsonyabb) / hip height (lower when crouching)
  const part = (c, hs, col, em) => rbox(items, rg, c, hs, col, 0, em, fa, fc);
  part([-0.14, hy / 2, 0], [0.1, hy / 2, 0.12], [38, 40, 58]);          // lábak / legs
  part([0.14, hy / 2, 0], [0.1, hy / 2, 0.12], [38, 40, 58]);
  part([0, hy + 0.03, 0], [0.26, 0.06, 0.15], [124, 90, 52]);           // öv / belt
  part([0, hy + 0.4, 0], [0.25, 0.34, 0.15], [52, 92, 128]);            // törzs / torso
  part([0, hy + 0.46, -0.155], [0.16, 0.18, 0.012], [214, 178, 98]);    // címer / emblem
  part([-0.31, hy + 0.7, 0], [0.1, 0.06, 0.13], [92, 98, 116]);         // vállvédők / shoulder pads
  part([0.31, hy + 0.7, 0], [0.1, 0.06, 0.13], [92, 98, 116]);
  part([0, hy + 0.92, 0], [0.14, 0.15, 0.14], [222, 178, 148]);         // fej / head
  part([0, hy + 1.09, 0.02], [0.155, 0.06, 0.155], [36, 28, 44]);       // haj / hair
  part([0, hy + 0.93, -0.145], [0.1, 0.025, 0.01], [24, 24, 36]);       // szemek / eyes
  part([0.08 * sin(3 * tm), hy + 0.38, 0.2], [0.22, 0.4, 0.025], [150, 38, 52]);   // vörös köpeny / red cape
  const hand = [o.sw[0], o.sw[1], o.sw[2]];
  rbar(items, rg, [0.3, hy + 0.66, 0], hand, 0.07, 0.07, [52, 92, 128], 0, false, fa, fc);   // kardot tartó kar / sword arm
  let oh = o.off ? o.off : [-0.3, hy + 0.15, -0.2];
  if (o.sh > 0.05) oh = [-0.3, hy + 0.5, -0.45];
  rbar(items, rg, [-0.3, hy + 0.66, 0], oh, 0.07, 0.07, [52, 92, 128], 0, false, fa, fc);    // másik kar / other arm
  const d = pDir(o.sw), raw = cross3(d, [0, 1, 0]), gu = norm3(dot3(raw, raw) < 1e-4 ? [1, 0, 0] : raw), gc = add3(hand, mul3(d, 0.1));
  const bc = o.gl ? o.gl : [204, 212, 230];
  rbar(items, rg, sub3(hand, mul3(d, 0.15)), gc, 0.04, 0.04, [60, 44, 36], 0.2, false, fa, fc);          // markolat / handle
  rbar(items, rg, gc, add3(hand, mul3(d, 1.3)), 0.05, 0.015, bc, 0.2, !!o.gl, fa, fc);                   // penge (képességek alatt izzik) / blade (glows during skills)
  rbar(items, rg, sub3(gc, mul3(gu, 0.14)), add3(gc, mul3(gu, 0.14)), 0.03, 0.03, [196, 160, 80], 0.3, false, fa, fc);   // keresztvas / cross-guard
  if (o.sh > 0.05) {                                           // pajzs védekezés közben / shield while guarding
    rbox(items, rg, [-0.3, hy + 0.5, -0.5], [0.3 * o.sh + 0.01, 0.34 * o.sh + 0.01, 0.04], [64, 112, 172], 0.3, false, fa, fc);
    rbox(items, rg, [-0.3, hy + 0.5, -0.545], [0.1 * o.sh + 0.005, 0.1 * o.sh + 0.005, 0.012], [230, 196, 100], 0.4, true, fa, fc);
  }
}

// ---------- a világ: ami sosem változik, itt EGYSZER számolódik ki, nem minden képkockán / the world: everything that never changes is computed ONCE here, not every frame ----------
const STARS = [];
for (let i = 0; i < 70; i++) { const az = 2 * PI * hash(i, 1), el = 0.1 + 1.3 * hash(i, 2); STARS.push([cos(el) * sin(az), sin(el), -cos(el) * cos(az)]); }
const PIL = [];                                                // romos oszlopok: törzsdoboz + fejdoboz / ruined pillars: shaft box + cap box
for (let i = 0; i < 9; i++) {
  const a = 2 * PI * i / 9 + 0.3, x = ARC[0] + 10.5 * cos(a), z = ARC[1] + 10.5 * sin(a), h = 4 + 4 * hash(i, 5), w = 0.6 + 0.3 * hash(i, 6);
  PIL.push({c1: [x, h / 2, z], h1: [w, h / 2, w], c2: [x, h + 0.12, z], h2: [w + 0.12, 0.12, w + 0.12]});
}
const RUB = [];                                                // kőtörmelék / rubble stones
for (let i = 0; i < 14; i++) {
  const a = 2 * PI * hash(i, 11), r = 4.5 + 5 * hash(i, 12);
  RUB.push({c: [ARC[0] + r * cos(a), 0.12, ARC[1] + r * sin(a)], h: [0.2 + 0.2 * hash(i, 13), 0.12, 0.2 + 0.15 * hash(i, 14)]});
}
const BR = [[-3.8, -8.5], [3.8, -8.5], [-7, -3], [7, -3]];     // tűzkosarak (x, z) / braziers (x, z)
const EMB = [];                                                // parázs: rögzített véletlenszámok parazsanként / embers: fixed random numbers per ember
for (let i = 0; i < 36; i++) EMB.push({a: hash(i, 1), b: hash(i, 2), c: hash(i, 3), d: hash(i, 4)});
function aPt(r, a) { return [ARC[0] + r * cos(a), 0, ARC[1] + r * sin(a)]; }
function mkFloor(seg) {                                        // kőaréna: 4 csempegyűrű; a világbeli pontok és színek előre kiszámolva / stone arena: 4 rings of tiles; world points and colours are precomputed
  const R = [0, 2.2, 4.6, 7.4, 10.5], out = [];
  for (let j = 0; j < 4; j++) for (let i = 0; i < seg; i++) {
    const a0 = 2 * PI * i / seg, a1 = 2 * PI * (i + 1) / seg;
    const pw = j === 0 ? [aPt(R[1], a0), aPt(R[1], a1), aPt(0, 0)] : [aPt(R[j], a0), aPt(R[j + 1], a0), aPt(R[j + 1], a1), aPt(R[j], a1)];
    const sh = ((i + j) % 2) ? 1 : 0.82, lit = 1.25 - 0.17 * j;
    out.push({pw: pw, col: rgb([58 * sh * lit, 48 * sh * lit, 78 * sh * lit])});
  }
  return out;
}
const FLOORS = [mkFloor(12), mkFloor(16), mkFloor(24)];        // minőségi szintenként egy felosztás / one tessellation per quality level
const MT = [];                                                 // két hegykoszorú: felső és alsó pontok (a magasságok egyszer kiszámolva) / two mountain rings: top and bottom points (heights computed once)
for (const L of [{r: 120, h0: 14, h1: 34, col: [40, 32, 62], sd: 3}, {r: 85, h0: 7, h1: 20, col: [28, 22, 46], sd: 7}]) {
  const N = 56, top = [], bot = [];
  for (let i = 0; i <= N; i++) {
    const a = 2 * PI * (i % N) / N;
    const h = L.h0 + (L.h1 - L.h0) * (0.5 + 0.28 * sin(3 * a + L.sd) + 0.22 * sin(7 * a + 2 * L.sd)) * (0.7 + 0.3 * hash(i % N, L.sd));
    const x = ARC[0] + L.r * cos(2 * PI * i / N), z = ARC[1] + L.r * sin(2 * PI * i / N);
    top.push([x, h, z]); bot.push([x, 0, z]);
  }
  MT.push({top: top, bot: bot, col: rgb(L.col)});
}
function drawMountains() {                                     // minden koszorú 1–2 nagy sokszögként rajzolódik 56 kis négyszög helyett / each ring is drawn as 1–2 big polygons instead of 56 small quads
  for (const L of MT) {
    let runT = [], runB = [];
    for (let i = 0; i < L.top.length; i++) {
      const vt = toCam(L.top[i]), vb = toCam(L.bot[i]);
      if (vt[2] >= NEARP && vb[2] >= NEARP) { runT.push(scrP(vt)); runB.push(scrP(vb)); }
      else {                                                   // a kamera mögött: az aktuális sáv lezárása / behind the camera: close the current strip
        if (runT.length >= 2) polygon(runT.concat(runB.reverse()), {fill: L.col, stroke: L.col, lw: 1});
        runT = []; runB = [];
      }
    }
    if (runT.length >= 2) polygon(runT.concat(runB.reverse()), {fill: L.col, stroke: L.col, lw: 1});
  }
}
function drawFloor(lv) {
  for (const T of FLOORS[QS[lv].seg]) {
    const v = clipPoly(T.pw.map(toCam));
    if (v.length < 3) continue;
    polygon(v.map(scrP), {fill: T.col, stroke: "#0f0b17", lw: 1});
  }
}

// ---------- 3) RAJZOLÁS / DRAWING ----------
draw(t => {
  fpsTick();                                                   // valós idejű képkocka-mérés (auto módban a minőségről is ez dönt) / real-time frame measurement (also decides the quality in auto mode)
  const lv = P.qual === "auto" ? ql : P.qual === "high" ? 2 : P.qual === "med" ? 1 : 0;   // az aktuális minőségi szint / current quality level
  const Q = QS[lv];

  // --- kamera / camera ---
  const amp = P.shk * 0.2 * (shakeT / 0.5);
  CP = [cEye[0] + amp * sin(61 * tm), cEye[1] + amp * cos(53 * tm), cEye[2]];
  FV = norm3(sub3(cAim, CP)); RV = norm3(cross3(FV, [0, 1, 0])); UV = cross3(RV, FV);
  FLn = cFL * (1 + 0.12 * zoomK);                              // nagyító ráközelítés parírozásnál és erős csapásnál / zoom punch on parry and power strike
  const yh = 300 + FLn * tan(asin(clamp(FV[1], -1, 1)));       // a horizont y koordinátája a képen / screen y of the horizon

  // --- ég, csillagok, hold, hegyek, köd / sky, stars, moon, mountains, fog ---
  const yEnd = clamp(yh, 0, 600);
  for (let y = 0; y < yEnd; y += Q.sky)
    rect(0, y, 1000, Q.sky + 1, {fill: rgb(mix([10, 8, 22], [88, 48, 84], pow(clamp(y / max(yh, 1), 0, 1), 2.2))), stroke: null});
  rect(0, max(yh, 0), 1000, 600 - max(yh, 0), {fill: "#120d1c", stroke: null});
  for (let i = 0; i < Q.stars; i++) {
    const d = STARS[i], qz = d[0] * FV[0] + d[1] * FV[1] + d[2] * FV[2];
    if (qz < 0.1) continue;
    const sx = 500 + FLn * (d[0] * RV[0] + d[1] * RV[1] + d[2] * RV[2]) / qz, sy = 300 - FLn * (d[0] * UV[0] + d[1] * UV[1] + d[2] * UV[2]) / qz;
    if (sx < 0 || sx > 1000 || sy < 0 || sy > yh) continue;
    rect(sx, sy, 2, 2, {fill: "#fff", stroke: null, alpha: 0.35 + 0.35 * sin(2 * tm + i)});
  }
  const mq = [dot3(MOON, RV), dot3(MOON, UV), dot3(MOON, FV)];
  let moonS = null;
  if (mq[2] > 0.1) {
    const mx = 500 + FLn * mq[0] / mq[2], my = 300 - FLn * mq[1] / mq[2], mr = FLn * 0.07;
    moonS = [mx, my];
    circle(mx, my, mr * 5, {fill: "#8a7ad0", stroke: null, alpha: 0.05});
    circle(mx, my, mr * 3, {fill: "#a898e8", stroke: null, alpha: 0.08});
    circle(mx, my, mr * 1.7, {fill: "#c8b8f0", stroke: null, alpha: 0.14});
    circle(mx, my, mr, {fill: "#f0e8ff", stroke: null});
    circle(mx - mr * 0.3, my - mr * 0.2, mr * 0.22, {fill: "#d8cdee", stroke: null});
    circle(mx + mr * 0.35, my + mr * 0.3, mr * 0.15, {fill: "#d8cdee", stroke: null});
  }
  drawMountains();
  if (P.fx && Q.fog > 0) for (let k = 0; k < 6; k += 6 / Q.fog) { const h = 24 + 22 * k; rect(0, yh - h * 0.6, 1000, h, {fill: "#5a3c6e", stroke: null, alpha: 0.05 * 6 / Q.fog}); }   // köd a horizonton (alacsonyabb minőségnél kevesebb, erősebb réteg) / fog on the horizon (fewer, stronger layers on lower quality)

  // --- padló, izzó rúnagyűrű, fénysugarak / floor, glowing rune ring, light shafts ---
  drawFloor(lv);
  wRing(0, 0.02, BASEZ, 3.6, phase === "enemy" ? "#ff6a4a" : "#6a8aff", 3, 0.6, Q.ring, 0.15 * tm, true);
  wRing(0, 0.02, BASEZ, 3.3, phase === "enemy" ? "#ff6a4a" : "#6a8aff", 1, 0.25, Q.ring, 0, false);
  if (P.fx && moonS && Q.shaft > 0) for (let k = 0; k < 5; k++) {
    if (Q.shaft === 3 && (k === 0 || k === 4)) continue;       // közepes minőség: csak a három középső sugár / medium quality: only the three middle shafts
    const bx = moonS[0] + (k - 2) * 190 + 40 * sin(0.3 * tm + k);
    polygon([[moonS[0] - 6, moonS[1]], [moonS[0] + 6, moonS[1]], [bx + 70, 640], [bx - 70, 640]], {fill: "#9fb4ff", stroke: null, alpha: 0.035});
  }

  // --- tárgyak mélység szerint rendezve: oszlopok, törmelék, tűzkosarak, ellenség, játékos / objects, depth sorted: pillars, rubble, braziers, enemy, player ---
  const items = [];
  for (const q of PIL) { obox(items, q.c1, AX, q.h1, [70, 62, 86], 0, false); obox(items, q.c2, AX, q.h2, [84, 74, 100], 0, false); }
  for (const q of RUB) obox(items, q.c, AX, q.h, [62, 54, 76], 0, false);
  for (let i = 0; i < BR.length; i++) {
    const b = BR[i], fk = 0.8 + 0.2 * sin(9 * tm + i * 2);
    obox(items, [b[0], 0.45, b[1]], AX, [0.22, 0.45, 0.22], [70, 62, 86], 0, false);
    obox(items, [b[0], 0.97, b[1]], AX, [0.34, 0.08, 0.34], [90, 80, 100], 0, false);
    obox(items, [b[0], 1.2, b[1]], AX, [0.14, 0.2 * fk, 0.14], [255, 150, 60], 0.2, true);
  }
  let cur = null;                                              // az éppen jelzett csapás / the strike that is currently being telegraphed
  if (phase === "enemy" && et >= 0) for (const c of combo) if (c.res === 0) { cur = c; break; }
  let gl = {c: [255, 255, 255], a: 0};
  if (cur && et >= cur.st) gl = {c: AT[cur.ty].cl, a: clamp(0.35 + 0.65 * sstep(cur.he * 0.5, 1, (et - cur.st) / cur.wind), 0, 1)};
  const po = phase === "enemy" ? poseAt(et) : phase === "won" ? DEAD : PR;
  const rgE = phase === "enemy" ? enemyRigAt(et) : {o: [0, 0, BASEZ + zOff], ya: 0};
  addEnemy(items, rgE, po, gl);
  const pO = phase === "pAct" ? plAt(actKind, pt) : plIdle();
  addPlayer(items, pO, (phase !== "pAct" && hurtT > 0) ? 0.7 * hurtT / 0.5 : 0, [255, 50, 50]);
  flush(items);

  // --- kardnyomok (korábbi pillanatokból mintavételezve, így mindig helyesek) / sword trails (sampled from earlier moments, so they are always correct) ---
  const trail = (tips, col, w) => {
    for (let j = 0; j + 1 < tips.length; j++) {
      const a = projW(tips[j]), b = projW(tips[j + 1]);
      if (!a || !b) continue;
      const al = (1 - j / tips.length) * clamp(hypot(a[0] - b[0], a[1] - b[1]) / 10, 0, 1) * 0.9;
      if (al < 0.02) continue;
      line(a[0], a[1], b[0], b[1], {stroke: rgb(col), lw: w * (1 - j / tips.length) + 2, alpha: al * 0.45});
      line(a[0], a[1], b[0], b[1], {stroke: "#ffffff", lw: 1.5, alpha: al * 0.8});
    }
  };
  if (phase === "enemy" && et > 0) {
    const tips = [], ci = curIdx(et), step = 0.014 * 12 / Q.trail;     // alacsonyabb minőségnél kevesebb minta, ugyanakkora nyomhossz / fewer samples on lower quality, same trail length
    for (let k = 0; k < Q.trail; k++) { const e = et - step * k; if (e < 0) break; tips.push(tipOf(enemyRigAt(e), poseAt(e), 2.6)); }
    trail(tips, ci >= 0 ? AT[combo[ci].ty].cl : [255, 255, 255], 9);
  }
  if (phase === "pAct" && actKind !== "heal" && actKind !== "guard") {
    const tips = [], nT = Q.trail + 2, step = 0.012 * 14 / nT;
    for (let k = 0; k < nT; k++) {
      const tt = pt - step * k; if (tt < 0) break;
      const o = plAt(actKind, tt);
      tips.push(rp({o: [o.x, o.y, o.z], ya: o.yaw}, add3([o.sw[0], o.sw[1], o.sw[2]], mul3(pDir(o.sw), 1.35))));
    }
    trail(tips, actKind === "power" ? GLC.power : actKind === "whirl" ? GLC.whirl : [255, 240, 192], 9);
  }

  // --- képességek effektjei / skill effects ---
  if (phase === "pAct") {
    if (actKind === "power" && pt > 0.9 && pt < 1.4) wRing(pO.x, 0.03, pO.z - 1.0, 0.4 + 14 * (pt - 0.9), "#ffb060", 5, 0.8 * (1 - (pt - 0.9) / 0.5), Q.ring, 0, false);   // lökéshullám / shockwave
    if (actKind === "whirl" && pt > 0.4 && pt < 1.3) wRing(pO.x, 0.03, pO.z, 1.5, "#6fe0ff", 3, 0.6, 30, 6 * pt, true);
    if (actKind === "heal" && pt > 0.35 && pt < 1.35) for (let i = 0; i < 22; i++) {                 // felszálló zöld szikrák / rising green sparks
      const yy = 0.1 + mod(1.4 * (pt - 0.35) + 1.6 * hash(i, 1), 2.2), a = 2 * PI * hash(i, 2) + 3 * pt;
      const p = projW([pO.x + 0.6 * cos(a), yy, pO.z + 0.6 * sin(a)]);
      if (p) circle(p[0], p[1], clamp(FLn * 0.03 / p[2], 1.5, 5), {fill: "#7dffb0", stroke: null, alpha: 0.85 * (1 - yy / 2.4)});
    }
  }
  if (impT > 0) {                                              // találati villanás az ellenségen / hit burst on the enemy
    const cp = projW([0, 1.8, BASEZ + zOff]);
    if (cp) { const s = 1 - impT / 0.3; for (let k = 0; k < 12; k++) { const a = 2 * PI * k / 12 + hash(k, 3), l0 = 20 + 20 * s, l1 = l0 + 90 * s; line(cp[0] + l0 * cos(a), cp[1] + l0 * sin(a), cp[0] + l1 * cos(a), cp[1] + l1 * sin(a), {stroke: "#ffe9a0", lw: 4, alpha: 1 - s}); } }
  }
  if (guard && phase !== "pAct") {                             // kék védőburok a játékos körül / blue barrier around the player
    const pp = projW([PX, 1.1, PZ]);
    if (pp) { const r = FLn * 0.95 / pp[2]; circle(pp[0], pp[1], r, {fill: "#6aa8ff", stroke: "#bfe0ff", lw: 2, alpha: 0.12 + 0.05 * sin(5 * tm)}); }
  }
  if (P.fx) {
    for (let i = 0; i < BR.length; i++) {                      // a tűzkosarak fénye / brazier glow
      const p = projW([BR[i][0], 1.3, BR[i][1]]), fk = 0.8 + 0.2 * sin(9 * tm + i * 2);
      if (p) { const r = FLn * 1.8 / p[2]; circle(p[0], p[1], r, {fill: "#ff8a3c", stroke: null, alpha: 0.09 * fk}); circle(p[0], p[1], r * 0.4, {fill: "#ffc070", stroke: null, alpha: 0.14 * fk}); }
    }
    for (let i = 0; i < Q.emb; i++) {                          // lebegő parázs (a véletlenszámok előre kiszámolva) / floating embers (random numbers are precomputed)
      const E = EMB[i], yy = mod(tm * (0.35 + 0.5 * E.b) + 6 * E.c, 7);
      const p = projW([-9 + 18 * E.a + 0.7 * sin(0.7 * tm + i), yy, -13 + 15 * E.d]);
      if (p) circle(p[0], p[1], clamp(FLn * 0.025 / p[2], 0.8, 3.5), {fill: "#ffa860", stroke: null, alpha: 0.7 * (1 - yy / 7)});
    }
  }

  // --- parírozási szikrák és villanás / parry sparks and flash ---
  if (sparkT < 0.4) {
    const sp = projW(sparkW);
    if (sp) {
      for (let k = 0; k < 16; k++) {
        const a = 2 * PI * k / 16 + hash(k, 1), l0 = 18 + 40 * hash(k, 2), l1 = l0 + 340 * sparkT * (0.5 + hash(k, 3));
        line(sp[0] + l0 * cos(a), sp[1] + l0 * sin(a), sp[0] + l1 * cos(a), sp[1] + l1 * sin(a), {stroke: k % 2 ? "#ffe9a0" : "#ffffff", lw: 3, alpha: 1 - sparkT / 0.4});
      }
      circle(sp[0], sp[1], 24 + 420 * sparkT, {stroke: "#bff0ff", lw: 5, alpha: 1 - sparkT / 0.4});
    }
    rect(0, 0, 1000, 600, {fill: "#ffffff", stroke: null, alpha: 0.5 * max(0, 1 - sparkT / 0.22)});
  }

  // --- időzítő gyűrű a penge hegyén (segítség) / timing ring on the blade tip (helper) ---
  if (phase === "enemy" && P.cue && cur && et >= cur.st) {
    const left = cur.ht - et, tp = projW(tipOf(rgE, po, 2.4));
    const rx = tp ? clamp(tp[0], 80, 920) : 500, ry = tp ? clamp(tp[1], 110, 480) : 300;
    const inWin = et >= max(cur.st, cur.ht - P.win) && et <= cur.ht + P.win * 0.6;
    if (left < 0.75) {
      circle(rx, ry, 34, {stroke: inWin ? "#7dffb0" : "#ffffff", lw: 4, alpha: 0.9});
      if (left > 0) circle(rx, ry, 34 + 170 * clamp(left / 0.75, 0, 1), {stroke: rgb(AT[cur.ty].cl), lw: 4, alpha: 0.9});
      if (inWin) circle(rx, ry, 30, {fill: "#7dffb0", stroke: null, alpha: 0.3});
    }
  }

  // --- filmes hatás: színkorrekció, vignetta, találati villanás, sávok / film look: colour grade, vignette, hit flash, bars ---
  rect(0, 0, 1000, 300, {fill: "#2a1a5a", stroke: null, alpha: 0.07});
  rect(0, 300, 1000, 300, {fill: "#4a1a20", stroke: null, alpha: 0.05});
  if (hurtT > 0) {
    rect(0, 0, 1000, 600, {fill: "#a00010", stroke: null, alpha: 0.3 * hurtT / 0.5});
    for (let k = 0; k < 5; k++) ring(500, 300, 330 + k * 60, 420 + k * 60, {fill: "#e01020", stroke: null, alpha: 0.12 * hurtT / 0.5});
  }
  // vignetta: a nagy, félig átlátszó gyűrűk kitöltése drága, ezért alacsonyabb minőségnél kevesebb, kicsit erősebb gyűrű (hasonló hatás) / vignette: big semi-transparent rings are expensive to fill, so lower quality uses fewer, slightly stronger ones (similar look)
  if (lv === 2) for (let k = 0; k < 7; k++) ring(500, 300, 340 + k * 55, 520 + k * 55, {fill: "#000", stroke: null, alpha: 0.15});
  else if (lv === 1) for (let k = 0; k < 4; k++) ring(500, 300, 340 + k * 95, 520 + k * 95, {fill: "#000", stroke: null, alpha: 0.21});
  else for (let k = 0; k < 2; k++) ring(500, 300, 340 + k * 170, 520 + k * 170, {fill: "#000", stroke: null, alpha: 0.3});
  for (let k = 0; k < Q.grain; k++) rect(random() * 1000, random() * 600, 2, 2, {fill: "#fff", stroke: null, alpha: 0.04});
  if (P.bars) { rect(0, 0, 1000, 44, {fill: "#000", stroke: null}); rect(0, 556, 1000, 44, {fill: "#000", stroke: null}); }

  // --- kijelzők (HUD) / HUD ---
  rect(300, 52, 400, 14, {fill: "#2a1a22", stroke: "#000", lw: 2});
  rect(300, 52, 400 * ehpShow / MAXEH, 14, {fill: "#d6563a", stroke: null});
  text({hu: "A Rozsdás Őrző", en: "The Rust Warden"}, 500, 47, {size: 16, bold: true, color: "#e8dcc8", align: "center"});
  if (stagger) text({hu: "MEGTÁNTORODOTT: +50 % sebzés", en: "STAGGERED: +50 % damage"}, 500, 84, {size: 14, bold: true, color: "#8ad0ff", align: "center"});
  rect(640, 552, 350, 48, {fill: "#000", stroke: null, alpha: 0.5});                       // háttérpanel a játékos sávjai mögött / backing panel for the player's bars
  rect(690, 560, 280, 14, {fill: "#1a2a22", stroke: "#000", lw: 2});
  rect(690, 560, 280 * hpShow / MAXHP, 14, {fill: hp < 36 ? "#e04040" : "#4fd07a", stroke: null});
  text({hu: "Életerő", en: "HP"}, 684, 572, {size: 13, color: "#cfe8d8", align: "right"});
  text(fmt(hp, 0) + " / " + MAXHP, 830, 571, {size: 12, bold: true, color: "#fff", align: "center"});
  for (let k = 0; k < MAXEN; k++) circle(702 + k * 22, 588, 7, {fill: k < nrg ? "#ffd04a" : "#3a3044", stroke: "#000", lw: 2});
  text({hu: "Energia", en: "Energy"}, 684, 592, {size: 13, color: "#ffe9a0", align: "right"});
  if (guard) text({hu: "VÉDEKEZÉS", en: "GUARD"}, 975, 592, {size: 13, bold: true, color: "#8ac8ff", align: "right"});

  const banner = phase === "enemy" ? {hu: "AZ ELLENSÉG KÖRE", en: "ENEMY TURN"} : phase === "player" ? {hu: "A TE KÖRÖD", en: "YOUR TURN"} : {hu: "", en: ""};
  text(banner, 500, 100, {size: 20, bold: true, color: phase === "enemy" ? "#ff8a6a" : "#e8dcc8", align: "center"});
  if (phase === "enemy") {                                     // kombósor: az aktuális és a következő csapás látszik, a többi rejtve / combo row: the current and the next strike are shown, the rest are hidden
    const n = combo.length, w = 34, x0 = 500 - n * w / 2;
    let curI = -1;
    for (let i = 0; i < n; i++) if (combo[i].res === 0) { curI = i; break; }
    for (let i = 0; i < n; i++) {
      const c = combo[i], A = AT[c.ty], bx = x0 + i * w, shown = c.res !== 0 || i <= curI + 1;
      const col = c.res === 1 ? "#2f9e5a" : c.res === 2 ? "#a83232" : (i === curI ? rgb(A.cl) : "#3b3150");
      rect(bx + 2, 108, w - 4, 30, {fill: col, stroke: i === curI ? "#fff" : "#000", lw: i === curI ? 2 : 1, radius: 5});
      text(shown ? A.nm : "?", bx + w / 2, 130, {size: shown && A.nm.length > 1 ? 13 : 18, bold: true, color: c.res !== 0 ? "#fff" : (i === curI ? "#1a1020" : "#a89cc0"), align: "center"});
    }
    if (cur && et >= cur.st) text(AT[cur.ty].name, 500, 158, {size: 16, bold: true, color: rgb(AT[cur.ty].cl), align: "center"});
    text({hu: "Nyomd az F billentyűt (vagy kattints a PARÍROZÁS gombra), amikor a gyűrű a körre ér", en: "Press F (or click PARRY) when the ring closes on the circle"}, 20, 592, {size: 13, color: "#9a90a8"});
  }
  if (phase === "player") {                                    // képességlista billentyűkkel és költségekkel; amire nincs elég energia, szürke / skill list with keys and costs; unaffordable skills are greyed out
    const SK = [["attack", "A", {hu: "Támadás · 18–22 sebzés · +1 energia", en: "Attack · 18–22 dmg · +1 energy"}],
                ["power", "S", {hu: "Erős csapás · 52 sebzés", en: "Power strike · 52 dmg"}],
                ["whirl", "D", {hu: "Forgószél · 3×22 sebzés", en: "Whirlwind · 3×22 dmg"}],
                ["heal", "H", {hu: "Gyógyítás · +35 életerő", en: "Heal · +35 HP"}],
                ["guard", "G", {hu: "Védekezés · fél sebzés · +1 energia", en: "Guard · half damage · +1 energy"}]];
    rect(16, 104, 350, 124, {fill: "#000", stroke: null, alpha: 0.4, radius: 8});
    for (let i = 0; i < SK.length; i++) {
      const ok = nrg >= COST[SK[i][0]];
      text(SK[i][1], 30, 128 + i * 22, {size: 14, bold: true, color: ok ? "#ffd04a" : "#6a5f78"});                       // a lenyomandó billentyű / the key to press
      text(tr(SK[i][2]) + (COST[SK[i][0]] ? "   [" + COST[SK[i][0]] + "]" : ""), 52, 128 + i * 22, {size: 14, color: ok ? "#e8dcc8" : "#6a5f78"});
    }
    text({hu: "Nyomd meg a sárga betűt, vagy válassz a Vezérlők fülön", en: "Press the yellow letter, or pick in the Controls tab"}, 20, 592, {size: 13, color: "#9a90a8"});
  }
  if (msgT > 0) text(msgL, 500, 215, {size: 44, bold: true, color: msgC, align: "center", alpha: min(1, msgT * 2.5)});
  for (const q of pops) {
    const p = q.at === "enemy" ? projW([0, 2.3, BASEZ + zOff]) : projW([pO.x, pO.y + 1.9, pO.z]);
    if (p) text(q.txt, p[0] + q.ox, p[1] - 30 - 46 * (1 - q.t), {size: 36, bold: true, color: q.col, align: "center", alpha: clamp(q.t * 2, 0, 1)});
  }
  if (phase === "lost" || phase === "won") {
    rect(0, 0, 1000, 600, {fill: "#000", stroke: null, alpha: 0.55});
    text(phase === "lost" ? {hu: "JÁTÉK VÉGE", en: "GAME OVER"} : {hu: "GYŐZELEM", en: "VICTORY"}, 500, 290, {size: 70, bold: true, color: phase === "lost" ? "#e04040" : "#ffd27a", align: "center"});
    text({hu: "Nyomd meg az Entert, vagy kattints az Újrakezdés gombra", en: "Press Enter or click Restart"}, 500, 340, {size: 22, color: "#d8d0e0", align: "center"});
  }

  // --- FPS-számláló (bal fent, a cím alatt) / FPS counter (top left, under the title) ---
  if (P.fpsOn) {
    rect(14, 50, 186, 38, {fill: "#000", stroke: null, alpha: 0.6, radius: 6});
    if (fpsOk) text("FPS " + (fpsVal > 0 ? fmt(fpsVal, 0) : "…") + "  ·  " + (fpsVal > 0 ? fmt(frameMs, 1) : "…") + " ms", 22, 66,
      {size: 13, bold: true, color: fpsVal >= 55 ? "#7dffb0" : fpsVal >= 30 ? "#ffd04a" : "#ff6a6a"});
    else text({hu: "FPS: nem elérhető", en: "FPS: n/a"}, 22, 66, {size: 13, bold: true, color: "#9a90a8"});
    text(tr({hu: "Minőség: ", en: "Quality: "}) + tr(QN[lv]) + (P.qual === "auto" ? " (auto)" : ""), 22, 82, {size: 12, color: "#cfc8dc"});
  }

  show({hu: "Kör", en: "Turn"}, turn, "", 0);
  show({hu: "Életerőd", en: "Your HP"}, hp, "/ " + MAXHP, 0);
  show({hu: "Ellenség életereje", en: "Enemy HP"}, ehp, "/ " + MAXEH, 0);
  show({hu: "Energia", en: "Energy"}, nrg, "/ " + MAXEN, 0);
  show({hu: "Sikeres parírozások", en: "Successful parries"}, parries, "", 0);
  show({hu: "Támadások a kombóban", en: "Strikes in this combo"}, phase === "enemy" ? combo.length : 0, "", 0);
  show({hu: "Képkockasebesség", en: "Frame rate"}, fpsOk ? fmt(fpsVal, 0) : "n/a", "FPS");
  show({hu: "Grafikai szint", en: "Quality level"}, tr(QN[lv]), "");
  plot({hu: "Életerőd", en: "Your HP"}, hp, {unit: "HP", color: C.green, min: 0, max: MAXHP, group: "hp"});
  plot({hu: "Ellenség életereje", en: "Enemy HP"}, ehp, {unit: "HP", color: C.red, min: 0, max: MAXEH, group: "hp2"});
  plot("FPS", fpsVal, {unit: "FPS", color: C.blue, min: 0, group: "fps"});
});
